// Generated by AI (UnitTest MCP)
import { spawnSync } from "node:child_process";
import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import { afterEach, describe, expect, it } from "vitest";

const checker = join(
  dirname(fileURLToPath(import.meta.url)),
  "../../../scripts/adr-link-check.mjs"
);
const temporaryDirectories = [];

afterEach(() => {
  for (const directory of temporaryDirectories.splice(0)) {
    rmSync(directory, { recursive: true, force: true });
  }
});

/** A workspace with an ADR directory, and whatever ADRs the test writes into it. */
const workspace = (files) => {
  const root = mkdtempSync(join(tmpdir(), "mindleak-adr-links-"));
  temporaryDirectories.push(root);
  mkdirSync(join(root, "docs", "adr"), { recursive: true });
  for (const [name, body] of Object.entries(files)) {
    writeFileSync(join(root, "docs", "adr", name), body);
  }
  return root;
};

const runCheck = (root, args = []) =>
  spawnSync(process.execPath, [checker, ...args], {
    cwd: root,
    encoding: "utf8",
  });

describe("adr-link-check", () => {
  it("refuses a link whose target file does not exist", () => {
    // The real failure: three ADRs cited 0045-armed-means-finished.md, which
    // was never a filename. The link rendered normally and only broke when
    // somebody clicked it.
    const root = workspace({
      "0045-a-fleet-is-a-distributed-system.md": "# ADR-0045\n",
      "0061-delivery-is-queued-not-raced.md":
        "- Related: [ADR-0045](0045-armed-means-finished.md) (armed means finished)\n",
    });

    const result = runCheck(root);

    expect(result.status).toBe(1);
    expect(result.stderr).toMatch(
      /0061-delivery-is-queued-not-raced\.md links to 0045-armed-means-finished\.md/
    );
  });

  it("accepts a link that resolves", () => {
    const root = workspace({
      "0045-a-fleet-is-a-distributed-system.md": "# ADR-0045\n",
      "0061-delivery-is-queued-not-raced.md":
        "- Related: [ADR-0045](0045-a-fleet-is-a-distributed-system.md) (armed means finished)\n",
    });

    const result = runCheck(root);

    expect(result.status, `${result.stdout}\n${result.stderr}`).toBe(0);
  });

  it("accepts a link carrying a heading anchor", () => {
    // `](0045-slug.md#decision)` is still a link to a file that exists.
    const root = workspace({
      "0045-a-fleet-is-a-distributed-system.md": "# ADR-0045\n",
      "0061-delivery-is-queued-not-raced.md":
        "See [ADR-0045](0045-a-fleet-is-a-distributed-system.md#decision).\n",
    });

    const result = runCheck(root);

    expect(result.status, `${result.stdout}\n${result.stderr}`).toBe(0);
  });

  it("checks only the ADRs it is given, so the hook stays scoped", () => {
    // pre-commit passes the staged files. A broken link elsewhere is somebody
    // else's commit to fix, not a reason to block this one.
    const root = workspace({
      "0045-a-fleet-is-a-distributed-system.md": "# ADR-0045\n",
      "0061-delivery-is-queued-not-raced.md":
        "- Related: [ADR-0045](0045-a-fleet-is-a-distributed-system.md)\n",
      "0062-the-delivery-queue-is-ours-to-run.md":
        "- Related: [ADR-0045](0045-armed-means-finished.md)\n",
    });

    const scoped = runCheck(root, ["docs/adr/0061-delivery-is-queued-not-raced.md"]);
    const everything = runCheck(root);

    expect(scoped.status, `${scoped.stdout}\n${scoped.stderr}`).toBe(0);
    expect(everything.status).toBe(1);
  });

  it("ignores paths that are not numbered ADRs", () => {
    const root = workspace({
      "0045-a-fleet-is-a-distributed-system.md": "# ADR-0045\n",
    });

    const result = runCheck(root, ["docs/adr/README.md", "CHANGELOG.md"]);

    expect(result.status, `${result.stdout}\n${result.stderr}`).toBe(0);
  });
});
